code4='''from collections import Counter

def canon(pts):
    forms=[]
    for k in range(8):
        vals=[]
        for y,x in pts:
            if k<4: a,b=y,x
            else: a,b=y,-x
            for _ in range(k%4): a,b=b,-a
            vals.append((a,b))
        my=min(a for a,b in vals); mx=min(b for a,b in vals)
        forms.append(frozenset((a-my,b-mx) for a,b in vals))
    return min(forms,key=lambda s:sorted(s))

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); pts=[]
            while q:
                y,x=q.pop(); pts.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==col:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.append((col,pts))
    edges=[(c,p) for c,p in comps if any(y in (0,h-1) or x in (0,w-1) for y,x in p)]
    key_col,key=max(edges,key=lambda z:len(z[1]))
    groups={}
    for col,pts in comps: groups.setdefault(canon(pts),[]).append((col,pts))
    out=[row[:] for row in grid]
    choices=[]
    for shape,items in groups.items():
        if len(items)<2: continue
        for col,pts in items:
            if col==key_col: continue
            if not any(y in (0,h-1) or x in (0,w-1) for y,x in pts):
                choices.append((min(y for y,x in pts),min(x for y,x in pts),pts))
    if choices:
        _,_,pts=min(choices)
        for y,x in pts: out[y][x]=key_col
    return out
'''
